package com.garagedesk.controller; import com.garagedesk.entity.ServiceBay; import com.garagedesk.service.BayService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/bays") public class BayController{final BayService s;public BayController(BayService s){this.s=s;}@GetMapping public List<ServiceBay> all(){return s.all();}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ServiceBay create(@Valid @RequestBody ServiceBay x){return s.save(x);}@PutMapping("/{id}")public ServiceBay update(@PathVariable Long id,@Valid @RequestBody ServiceBay x){return s.update(id,x);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
